async function loadStudentLoginDetails(){
 const box=document.getElementById("studentLoginDetailsList");
 if(!box)return;
 const client=window.schooldeskSupabase;
 if(!client){box.textContent="Supabase कनेक्शन उपलब्ध नहीं है।";return;}
 box.innerHTML="<p>लोड हो रहा है…</p>";
 try{
  const {data:rows,error}=await client.from("students").select("student_name,email,student_login_id,status,admission_status").eq("is_deleted",false).order("id",{ascending:false});
  if(error)throw error;
  box.innerHTML="";
  if(!rows||!rows.length){box.textContent="कोई विद्यार्थी रिकॉर्ड नहीं मिला।";return;}
  const table=document.createElement("table");table.className="student-login-table";
  const thead=document.createElement("thead");thead.innerHTML="<tr><th>विद्यार्थी का नाम</th><th>Email</th><th>Student Login ID</th><th>स्थिति</th><th>Password</th><th>कार्रवाई</th></tr>";
  const tbody=document.createElement("tbody");
  for(const row of rows){
   const tr=document.createElement("tr");
   const name=document.createElement("td");name.textContent=row.student_name||"—";
   const emailCell=document.createElement("td");emailCell.textContent=row.email||"—";
   const login=document.createElement("td");login.textContent=row.student_login_id||"—";
   const status=document.createElement("td");status.textContent=row.status||"—";
   const pass=document.createElement("td");pass.textContent="सुरक्षित (Admin नहीं देख सकता)";
   const action=document.createElement("td");const reset=document.createElement("button");reset.type="button";reset.className="approve-btn";reset.textContent="Reset Link भेजें";
   reset.onclick=async()=>{
    if(String(row.status||"").toLowerCase()!=="active"||String(row.admission_status||"").toLowerCase()!=="approved"){alert("Password बनाने का लिंक केवल Admission Approve होने के बाद भेजा जा सकता है।");return;}
    if(!confirm((row.student_name||"इस विद्यार्थी")+" की पहचान स्कूल रिकॉर्ड से सत्यापित करने के बाद ही Reset Link भेजें। क्या आपने पहचान सत्यापित कर ली है?"))return;
    reset.disabled=true;
    try{
     const email=String(row.email||"").trim().toLowerCase();
     if(!email)throw new Error("विद्यार्थी का पंजीकृत ईमेल उपलब्ध नहीं है। पहले Email जोड़ें।");
     await schooldeskSendPasswordSetupLink(client,email);
     alert("Supabase ने Password Setup ईमेल भेजने का अनुरोध स्वीकार किया है। ईमेल पहुँचना SMTP सेटिंग पर निर्भर है। पुराना पासवर्ड नहीं बदलेगा; विद्यार्थी लिंक खोलकर नया Password बनाएगा।");
    }catch(err){alert("Reset Link नहीं भेजा जा सका: "+(err?.message||"ईमेल/URL सेटिंग जाँचें।"));}
    finally{reset.disabled=false;}
   };
   if(!row.email&&String(row.status||"").toLowerCase()!=="left"){const addEmail=document.createElement("button");addEmail.type="button";addEmail.className="approve-btn";addEmail.textContent="Email जोड़ें";addEmail.onclick=async()=>{const entered=prompt((row.student_name||"विद्यार्थी")+" का सही Email दर्ज करें:");if(entered===null)return;const clean=entered.trim().toLowerCase();if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(clean)){alert("कृपया सही Email ID दर्ज करें।");return;}addEmail.disabled=true;const {error}=await client.from("students").update({email:clean}).eq("student_login_id",String(row.student_login_id||"")).eq("is_deleted",false);if(error){alert("Email सेव नहीं हुआ: "+error.message);addEmail.disabled=false;return;}alert("Email सेव हो गया। अब विद्यार्थी इसी Email से Student Sign Up करेगा; सिस्टम पुराने रिकॉर्ड से उसका खाता जोड़ेगा।");loadStudentLoginDetails();};action.append(addEmail);}
   action.append(reset);tr.append(name,emailCell,login,status,pass,action);tbody.append(tr);
  }
  table.append(thead,tbody);box.append(table);
 }catch(err){box.textContent="विद्यार्थियों की सूची लोड नहीं हुई: "+(err?.message||"Database permission जाँचें।");}
}


async function loadStudentRecycleBin(){
 const client=window.schooldeskSupabase,activeBox=document.getElementById("recycleActiveList"),deletedBox=document.getElementById("recycleDeletedList");
 if(!activeBox||!deletedBox)return;
 if(!client){activeBox.textContent="Supabase कनेक्शन उपलब्ध नहीं है।";return;}
 activeBox.textContent="लोड हो रहा है…";deletedBox.textContent="लोड हो रहा है…";
 try{
  const {data:userData,error:userError}=await client.auth.getUser();
  if(userError||!userData?.user||userData.user.id!==window.SCHOOLDESK_ADMIN_UID)throw new Error("केवल सत्यापित Admin इस सुविधा का उपयोग कर सकता है।");
  const {data:rows,error}=await client.from("students").select("id,student_login_id,admission_no,student_name,status,auth_user_id,is_deleted,deleted_at").order("id",{ascending:false});
  if(error)throw error;
  const active=(rows||[]).filter(r=>!r.is_deleted),deleted=(rows||[]).filter(r=>r.is_deleted);
  const render=(target,list,isDeleted)=>{
   target.innerHTML="";
   if(!list.length){target.textContent=isDeleted?"Recycle Bin खाली है।":"कोई Active Student नहीं मिला।";return;}
   list.forEach(row=>{
    const wrap=document.createElement("div");wrap.className="recycle-row";
    const check=document.createElement("input");check.type="checkbox";check.className="recycle-select";check.value=String(row.id);check.setAttribute("aria-label",(row.student_name||"Student")+" चुनें");check.disabled=isDeleted;
    const info=document.createElement("div");const strong=document.createElement("strong");strong.textContent=(row.student_name||"Student")+" · "+(row.student_login_id||"No Login ID");const small=document.createElement("small");small.textContent="स्थिति: "+(row.status||"—")+(isDeleted&&row.deleted_at?" · हटाया गया: "+new Date(row.deleted_at).toLocaleString():"");info.append(strong,small);
    const actions=document.createElement("div");
    if(isDeleted){
     const restore=document.createElement("button");restore.type="button";restore.className="restore";restore.textContent="Restore";restore.onclick=()=>restoreCloudStudent(row);actions.append(restore);
     const hard=document.createElement("button");hard.type="button";hard.className="hard-delete";hard.textContent="Permanent Delete";hard.onclick=()=>permanentlyDeleteCloudStudent(row);actions.append(hard);
    }else{
     const del=document.createElement("button");del.type="button";del.className="soft-delete";del.textContent="Recycle Bin में भेजें";del.onclick=()=>softDeleteCloudStudent(row);actions.append(del);
    }
    wrap.append(check,info,actions);target.append(wrap);
   });
  };
  render(activeBox,active,false);render(deletedBox,deleted,true);
 }catch(err){activeBox.textContent="सूची लोड नहीं हुई: "+(err?.message||"Permission जाँचें।");deletedBox.textContent="";}
}
async function softDeleteCloudStudent(row){
 const client=window.schooldeskSupabase;
 if(!confirm((row.student_name||"इस विद्यार्थी")+" को Recycle Bin में भेजें? इसका Student Login बंद हो जाएगा।"))return;
 const {data:u,error:ue}=await client.auth.getUser();if(ue||u?.user?.id!==window.SCHOOLDESK_ADMIN_UID){alert("Admin session सत्यापित नहीं है।");return;}
 const {error}=await client.from("students").update({is_deleted:true,deleted_at:new Date().toISOString(),}).eq("id",row.id);
 if(error){alert("रिकॉर्ड Recycle Bin में नहीं गया: "+error.message);return;}
 alert("विद्यार्थी Recycle Bin में भेज दिया गया।");loadStudentRecycleBin();renderApprovals();loadStudentLoginDetails();
}
async function restoreCloudStudent(row){
 const client=window.schooldeskSupabase;
 if(!confirm((row.student_name||"इस विद्यार्थी")+" को वापस Active सूची में लाएँ?"))return;
 const {data:u,error:ue}=await client.auth.getUser();if(ue||u?.user?.id!==window.SCHOOLDESK_ADMIN_UID){alert("Admin session सत्यापित नहीं है।");return;}
 const {error}=await client.from("students").update({is_deleted:false,deleted_at:null,}).eq("id",row.id);
 if(error){alert("Restore नहीं हुआ: "+error.message);return;}
 alert("विद्यार्थी वापस Active सूची में आ गया।");loadStudentRecycleBin();renderApprovals();loadStudentLoginDetails();
}
async function permanentlyDeleteCloudStudent(row){
 const client=window.schooldeskSupabase;
 const phrase=prompt("यह कार्रवाई वापस नहीं हो सकती। स्थायी रूप से हटाने के लिए DELETE लिखें:");
 if(phrase!=="DELETE"){if(phrase!==null)alert("पुष्टि सही नहीं है।");return;}
 if(!confirm("आखिरी पुष्टि: "+(row.student_name||"इस विद्यार्थी")+" का Student Login Account और Student Database Row स्थायी रूप से हटाया जाएगा। जारी रखें?"))return;
 const {data:u,error:ue}=await client.auth.getUser();if(ue||u?.user?.id!==window.SCHOOLDESK_ADMIN_UID){alert("Admin session सत्यापित नहीं है।");return;}
 try{
  const {data,error}=await client.functions.invoke("schooldesk-delete-student",{body:{student_id:String(row.id)}});
  if(error)throw error;
  if(!data?.success)throw new Error(data?.error||"Server ने delete की पुष्टि नहीं की।");
  alert("Student Login Account और Student Record स्थायी रूप से हटा दिए गए।");loadStudentRecycleBin();renderApprovals();loadStudentLoginDetails();
 }catch(err){const details=err?.context?.body?.error||err?.context?.body?.message||err?.message||"अज्ञात नेटवर्क त्रुटि";alert("Permanent Delete पूरा नहीं हुआ: "+details+"\nSupabase Edge Function और Admin Login जाँचें।");}
}
async function recycleDeleteSelected(){
 const client=window.schooldeskSupabase;
 const boxes=[...document.querySelectorAll("#recycleActiveList .recycle-select:checked")];
 if(!client){alert("Supabase कनेक्शन उपलब्ध नहीं है।");return;}
 if(!boxes.length){alert("पहले विद्यार्थी चुनें।");return;}
 if(!confirm(boxes.length+" चुने हुए विद्यार्थियों को Recycle Bin में भेजें? उनका Student Login बंद हो जाएगा।"))return;
 const {data:userData,error:userError}=await client.auth.getUser();
 const admin=userData?.user;
 if(userError||!admin||admin.id!==window.SCHOOLDESK_ADMIN_UID){alert("केवल सत्यापित Admin ही विद्यार्थियों को हटाने की अनुमति रखता है।");return;}
 const deletedAt=new Date().toISOString();
 for(const box of boxes){
  const {error}=await client.from("students").update({is_deleted:true,deleted_at:deletedAt,}).eq("id",box.value).neq("auth_user_id",window.SCHOOLDESK_ADMIN_UID);
  if(error){alert("एक रिकॉर्ड हटाते समय त्रुटि: "+error.message);break;}
 }
 loadStudentRecycleBin();renderApprovals();loadStudentLoginDetails();
}
async function recycleDeleteAll(){
 const client=window.schooldeskSupabase;
 if(!confirm("क्या आप सभी Active विद्यार्थियों को Recycle Bin में भेजना चाहते हैं? Admin Account सुरक्षित रहेगा।"))return;
 const {data:u,error:ue}=await client.auth.getUser();if(ue||u?.user?.id!==window.SCHOOLDESK_ADMIN_UID){alert("Admin session सत्यापित नहीं है।");return;}
 const {error}=await client.from("students").update({is_deleted:true,deleted_at:new Date().toISOString(),}).eq("is_deleted",false).neq("auth_user_id",window.SCHOOLDESK_ADMIN_UID);
 if(error){alert("सभी विद्यार्थियों को हटाया नहीं जा सका: "+error.message);return;}
 alert("सभी Active Student Records Recycle Bin में भेज दिए गए।");loadStudentRecycleBin();renderApprovals();loadStudentLoginDetails();
}
document.addEventListener("click",ev=>{
 if(ev.target?.id==="recycleRefresh")loadStudentRecycleBin();
 if(ev.target?.id==="recycleDeleteSelected")recycleDeleteSelected();
 if(ev.target?.id==="recycleDeleteAll")recycleDeleteAll();
});

