 const rb=$("mySchoolRecords");if(rb){rb.innerHTML="<h4>Homework, Results, Fees & Leave</h4>";const records=getSchoolRecords().filter(r=>r.student===id);if(!records.length)rb.append(document.createTextNode("अभी कोई school record उपलब्ध नहीं है।"));records.slice().reverse().forEach(r=>{const p=document.createElement("p");p.textContent=r.type.toUpperCase()+" — "+r.title+": "+r.details;rb.append(p)})}
