 [select,recordSelect].forEach(s=>{const old=s.value;s.innerHTML='<option value="">Select student</option>';Object.keys(users).forEach(id=>{const o=document.createElement("option");o.value=id;o.textContent=(users[id].name||users[id].application?.fullName||id)+" ("+id+")";s.append(o)});if(users[old])s.value=old});
