$("manageStudent").addEventListener("change",()=>{const id=$("manageStudent").value,u=getUsers()[id];$("editStudentName").value=u?.name||u?.application?.fullName||"";$("editStudentEmail").value=u?.email||u?.application?.contactEmail||"";$("editStudentClass").value=u?.application?.studentClass||"";$("editStudentStatus").value=u?.status||"Pending Admin Approval";$("editApplicationStatus").value=u?.application?.status||""});
$("saveStudentRecord").onclick=()=>{const id=$("manageStudent").value;if(!id)return alert("पहले student चुनें।");const users=getUsers(),u=users[id];if(!u)return alert("Student record नहीं मिला। सूची refresh करके फिर कोशिश करें।");const newName=$("editStudentName").value.trim();if(!newName)return alert("Student name खाली नहीं हो सकता।");u.name=newName;u.email=$("editStudentEmail").value.trim();u.status=$("editStudentStatus").value;const classValue=$("editStudentClass").value.trim();if(u.application){u.application.fullName=newName;u.application.studentClass=classValue;const appStatus=$("editApplicationStatus").value;if(appStatus)u.application.status=appStatus;}else if($("editApplicationStatus").value){u.application={fullName:newName,studentClass:classValue,status:$("editApplicationStatus").value,submittedAt:new Date().toISOString()};}saveUsers(users);renderAdminTools();renderApprovals();if(u.application)renderMyApplication(id);alert("Student record saved successfully.")};
$("deleteStudentRecord").onclick=()=>{const id=$("manageStudent").value;if(!id)return alert("पहले student चुनें।");if(!confirm("इस student को Active list से हटाकर School Left Students Register में सुरक्षित रखें?"))return;const users=getUsers(),u=users[id];if(!u)return alert("Student record नहीं मिला।");const archived=getLeftStudents();if(!archived.some(r=>r.id===id)){archived.push({archiveId:"LEFT-"+Date.now()+"-"+id,id,record:u,leftAt:new Date().toISOString(),reason:"School Left"});saveLeftStudents(archived)}delete users[id];saveUsers(users);$("manageStudent").value="";$("editStudentName").value="";$("editStudentEmail").value="";$("editStudentClass").value="";$("editApplicationStatus").value="";renderAdminTools();renderApprovals();alert("Student active list से हटा दिया गया है। उसका रिकॉर्ड School Left Students Register में सुरक्षित है।")};
