 ["profile","👤","My Profile"],["addstudent","➕","Add Student"],["timetable","🗓️","Timetable"],["results","🎓","Exams & Results"],["fees","💳","Fees"],["notices","📢","Notices"],["leave","🌴","Leave Application"],["certificates","📜","Certificates"]
