   const prev=student.application||{};student.name=(d.name||"").trim();student.email=(d.email||"").trim();student.className=(d.className||"").trim();student.application={...prev,fullName:student.name,studentClass:student.className,fatherName:(d.fatherName||"").trim(),motherName:(d.motherName||"").trim(),phone:(d.phone||"").trim(),dob:d.dob||"",address:(d.address||"").trim(),admissionNumber:(d.admissionNumber||"").trim(),session:(d.session||"").trim(),contactEmail:student.email,photoDataUrl,status:prev.status||"Profile Saved",updatedAt:new Date().toISOString()};allUsers[id]=student;saveUsers(allUsers);const m=content.querySelector("#studentAddAccountMessage");if(m)m.textContent="आपकी Student details सेव हो गई हैं।";renderStudentIdentity(id);renderMyApplication(id);alert("Student details सफलतापूर्वक सेव हो गईं।");return;
