function normalizedClass(value){return String(value||"").toLowerCase().replace(/class/g,"").replace(/[^0-9a-z]/g,"").trim()}
function renderExamSchemes(){const box=$("savedExamSchemes");if(!box)return;const rows=readStore(examKey);const groups={};rows.forEach(r=>{const k=r.schemeId||r.id;groups[k]??={...r,papers:[]};groups[k].papers.push(r)});const list=Object.values(groups);box.innerHTML="<h4>Saved Exam Schemes</h4>"+(list.length?list.slice().reverse().map(g=>`<div class="portal-record"><strong>Class ${safeText(g.className)} · ${safeText(g.examName||"Exam")} · ${safeText(g.session||"")}</strong><div>${g.papers.length} papers: ${g.papers.map(x=>safeText(x.subject)).join(", ")}</div><button type="button" class="reject-btn" data-delete-exam-scheme="${safeText(g.schemeId||g.id)}">Delete Scheme</button></div>`).join(""):"<p>अभी कोई परीक्षा कार्यक्रम सेव नहीं है।</p>");box.querySelectorAll("[data-delete-exam-scheme]").forEach(b=>b.onclick=()=>{if(!confirm("यह पूरी परीक्षा योजना हटाएँ?"))return;writeStore(examKey,readStore(examKey).filter(r=>(r.schemeId||r.id)!==b.dataset.deleteExamScheme));renderExamSchemes()})}
