const saveExamButton=$("saveExamScheme");if(saveExamButton)saveExamButton.onclick=()=>{const className=$("examClass").value,examName=$("examName").value.trim(),session=$("examSession").value.trim(),paperRows=[...document.querySelectorAll("#examPaperRows .exam-paper-row")];if(!examName){alert("परीक्षा का नाम भरें।");return}if(!paperRows.length){alert("कम से कम एक पेपर जोड़ें।");return}const papers=[];for(const row of paperRows){const subject=row.querySelector(".paper-subject").value.trim(),paper=row.querySelector(".paper-number").value.trim(),date=row.querySelector(".paper-date").value,time=row.querySelector(".paper-time").value.trim(),shift=row.querySelector(".paper-shift").value.trim(),day=row.querySelector(".paper-day").value.trim();if(!subject||!date||!time){alert("हर पेपर में विषय, तारीख और समय भरना जरूरी है।");return}papers.push({subject,paper,date,time,shift,day:day||(date?new Date(date+"T12:00:00").toLocaleDateString("hi-IN",{weekday:"long"}):"")})}const schemeId="EX"+Date.now(),all=readStore(examKey);papers.forEach((p,i)=>all.push({id:schemeId+"_"+i,schemeId,className,examName,session,...p,createdAt:new Date().toISOString()}));writeStore(examKey,all);$("examSchemeMessage").textContent=`Class ${className} की ${examName} योजना ${papers.length} पेपर के साथ सेव हो गई। अब इसी कक्षा के विद्यार्थी Admit Card डाउनलोड कर सकते हैं।`;$("examName").value="";document.querySelectorAll("#examPaperRows .exam-paper-row").forEach((r,i)=>{if(i)r.remove();else r.querySelectorAll("input").forEach(x=>x.value="")});renderExamSchemes();alert("Exam scheme सफलतापूर्वक सेव हो गई।")};
